#!/usr/bin/env python3
"""Extract storyboard spec from a watch page HTML with proper string scanning."""
import json, sys, re

def extract_spec(html):
    key = '"playerStoryboardSpecRenderer":{"spec":"'
    i = html.find(key)
    if i < 0:
        return None
    j = i + len(key)
    out = []
    while j < len(html):
        c = html[j]
        if c == '\\':
            out.append(html[j:j+2]); j += 2; continue
        if c == '"':
            break
        out.append(c); j += 1
    raw = '"' + ''.join(out) + '"'
    return json.loads(raw)

def extract_player_response(html):
    m = re.search(r'ytInitialPlayerResponse\s*=\s*', html)
    i = m.end()
    # find first '{' then brace-match with string awareness
    while html[i] != '{':
        i += 1
    depth = 0; j = i; in_str = False; esc = False
    while j < len(html):
        c = html[j]
        if in_str:
            if esc: esc = False
            elif c == '\\': esc = True
            elif c == '"': in_str = False
        else:
            if c == '"': in_str = True
            elif c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    break
        j += 1
    return json.loads(html[i:j+1])

if __name__ == '__main__':
    html = open(sys.argv[1]).read()
    pr = extract_player_response(html)
    vd = pr.get('videoDetails', {})
    sb = pr.get('storyboards', {}).get('playerStoryboardSpecRenderer', {}).get('spec')
    print('title:', vd.get('title'))
    print('duration:', vd.get('lengthSeconds'))
    print('status:', pr.get('playabilityStatus', {}).get('status'))
    print('spec:', sb)

